def solve_game(N):
    # W[n] is True if the player whose turn it is at n wins (Type A for N=1, but here W[1] is what we check)
    # W[n] is defined for n from 1 to N-1.
    W = {} 

    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move to n+1
        n_plus_1 = n + 1
        if n_plus_1 <= N:
            if n_plus_1 == N:
                can_win = True
            else:
                # If the opponent loses from n+1, we win
                if not W.get(n_plus_1, False): # Defaulting to False if somehow not calculated, but it should be calculated
                    can_win = True

        # Check move to 2n
        two_n = 2 * n
        if two_n <= N:
            if two_n == N:
                can_win = True
            else:
                # If the opponent loses from 2n, we win
                if not W.get(two_n, False):
                    can_win = True

        W[n] = can_win

    # The game starts at n=1.
    return W.get(1, False) # True if Type A, False if Type B

results = {}
for N in range(1, 101):
    is_type_A = solve_game(N)
    if is_type_A:
        status = "A"
    else:
        status = "B"
    results[N] = status

print("N | Status")
print("-" * 10)
for N, status in results.items():
    print(f"{N:2} | {status}")

# Extract the sequence of Type B numbers
type_B_numbers = [N for N, status in results.items() if status == "B"]
print("\nType B numbers (up to 100):", type_B_numbers)
